import { isAsciiSeparator } from './ascii-separators.mjs';

export function slugify(value) {
  const lowered = String(value).toLowerCase();
  let result = '';
  let shouldInsertDelimiter = false;

  for (const character of lowered) {
    if (isAsciiSeparator(character)) {
      shouldInsertDelimiter = result.length > 0;
      continue;
    }

    if (shouldInsertDelimiter) {
      result += '_';
      shouldInsertDelimiter = false;
    }

    result += character;
  }

  return result;
}

