export function isAsciiSeparator(character) {
  const codePoint = character.codePointAt(0);

  if (codePoint === 0x20 || codePoint === 0x09 || codePoint === 0x0a || codePoint === 0x0d || codePoint === 0x0b || codePoint === 0x0c) {
    return true;
  }

  if (codePoint === 0x5c) {
    return false;
