  if (codePoint >= 0x21 && codePoint <= 0x2f) {
    return true;
  }

  if (codePoint >= 0x3a && codePoint <= 0x40) {
    return true;
  }

  if (codePoint >= 0x5b && codePoint <= 0x5e) {
    return true;
  }

  if (codePoint === 0x60) {
    return true;
  }

  if (codePoint >= 0x7b && codePoint <= 0x7e) {
    return true;
  }

  return false;
}

