function formatHelp(programName) {
  return `${formatUsage(programName)}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n`;
}

function formatError(programName, message) {
  return `${formatUsage(programName)}${programName}: error: ${message}\n`;
}

function canUseAsOptionValue(token) {
  if (token === undefined) {
    return false;
  }

  if (token === '-') {
    return true;
  }

  if (token.startsWith('--')) {
    return false;
  }

  if (token.startsWith('-')) {
    return NEGATIVE_NUMBER_PATTERN.test(token);
  }

  return true;
}

export function parseTest4Args(argv = process.argv.slice(2), programName = getProgramName()) {
  let aValue;
  const unknownTokens = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        code: 0,
        output: formatHelp(programName),
      };
    }

    if (token === '--a') {
      const nextToken = argv[index + 1];

      if (!canUseAsOptionValue(nextToken)) {
        return {
          kind: 'error',
          code: 2,
          output: formatError(programName, 'argument --a: expected one argument'),
        };
      }

      aValue = nextToken;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      aValue = token.slice(4);
      continue;
    }

    unknownTokens.push(token);
  }

  if (aValue === undefined) {
    return {
      kind: 'error',
      code: 2,
      output: formatError(programName, 'the following arguments are required: --a'),
    };
  }

  if (unknownTokens.length > 0) {
    return {
      kind: 'error',
      code: 2,
      output: formatError(programName, `unrecognized arguments: ${unknownTokens.join(' ')}`),
    };
  }

  return {
    kind: 'success',
    code: 0,
    value: aValue,
  };
}

